            justify-content: center;
            color: white;
            font-size: 24px;
            font-weight: bold;
        }

        .hexagon {
            width: 30px;
            height: 30px;
            background-color: white;
            clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
            margin-right: 10px;
        }

        .login-container {
            display: flex;
            justify-content: center;
            align-items: center;
            flex-grow: 1;
        }

        .login-panel {
            background-color: white;
            border-radius: 8px;
            padding: 30px;
            width: 350px;
            box-shadow: 0 4px 8px rgba(0,0,0,0.1);
            border: 1px solid #ddd;
        }

        .title {
            text-align: center;
            color: #333;
            margin-bottom: 30px;
            font-size: 24px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        label {
            display: block;
            margin-bottom: 5px;
            color: #555;
            font-weight: bold;
        }

        input[type="text"], input[type="password"] {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            border-radius: 4px;
            box-sizing: border-box;
        }

        .radio-group {
            margin: 20px 0;
        }

        .radio-option {
            margin-bottom: 10px;
        }

        input[type="radio"] {
            margin-right: 8px;
        }

        .btn-connect {
            background-color: #0074D9; /* Bright blue */
            color: white;
            border: none;
            padding: 12px 20px;
            width: 100%;
            border-radius: 4px;
            font-size: 16px;
            font-weight: bold;
            cursor: pointer;
            margin-top: 20px;
        }

        .btn-connect:hover {
            background-color: #005fa3;
        }

        .error-message {
            color: red;
            margin-bottom: 15px;
            text-align: center;
