exports.redirectToHome = (req, res) => {
  if (req.session.userId) {
    // Get user messages
    const userMessages = messages.filter(msg => msg.to === req.session.userId);

    res.render('home', {
      user: {
        id: req.session.userId,
        login: req.session.userLogin
      },
      messages: userMessages
    });
  } else {
    res.redirect('/login');
  }
};"}

