    border: none;
    padding: 12px 20px;
    width: 100%;
    border-radius: 4px;
    font-size: 16px;
    font-weight: bold;
    cursor: pointer;
    margin-top: 20px;
    transition: background-color 0.3s;
}

.btn-connect:hover {
    background-color: #005fa3;
}

.error-message {
    color: #ff4136;
    margin-bottom: 15px;
    text-align: center;
    padding: 10px;
    background-color: #ffeeee;
    border-radius: 4px;
    border: 1px solid #ffcccc;
}

