}

.message-item:last-child {
    border-bottom: none;
}

.message-from {
    font-weight: bold;
    color: #0074D9;
}

.message-date {
    float: right;
    color: #999;
    font-size: 0.9em;
}

.message-content {
    margin-top: 10px;
